updateFlowStamp.text:
function updateFlowStamp(asof, meta) {
  var stamp = document.getElementById('ift-stamp');
  if (!stamp) return;
  var disp = (BASE_DATA && BASE_DATA.as_of_display) || {};
  var asOfEn = disp.en || '';
  var asOfZh = disp.zh || '';
  if (!leaders.length || !asOfEn) {
    stamp.innerHTML = lz(
      "Board can't load right now — the plain-word calls below are from the last build",
      "看板暂时无法加载——下方结论来自上一次构建"
    );
    return;
  }
  var tipQ = feedTipRow(quotesStatus,'quotes');
  var tipT = feedTipRow(pulseStatus,'tape');
  var tipO = feedTipRow(flowStatus,'options');
  var head = feedHeadline(quotesStatus, pulseStatus, flowStatus);
  function tipRowHtml(r){
    return '<div class="ift-feed-row">'+lz(esc(r.en), esc(r.zh))+'</div>';
  }
  var tipHtml = '<div class="lens-body">'+tipRowHtml(tipQ)+tipRowHtml(tipT)+tipRowHtml(tipO)+'</div>';
  stamp.innerHTML = lz('Board built '+asOfEn+' · '+head.en, '看板构建于'+asOfZh+' · '+head.zh)
    + '<button type="button" class="lens-q" aria-label="Feed status">'
    + '?<span class="lens-src" data-lens-kind="define" hidden>'+tipHtml+'</span></button>';
}

